#pragma once
int runRawStemCheck(const char* path){Processor p(false);p.trackOffline=true;auto a=p.readAudio(juce::File{juce::String(path)});if(!a||a->buffer.getNumSamples()<a->rate*16)return 2042;p.audio=a;p.split(4,false);p.trackMode=true;p.trackGridReady=p.trackGridEdited=true;p.trackGrid.bpm=120;p.trackGrid.anchors={{0,0},{(double)a->buffer.getNumSamples(),a->buffer.getNumSamples()/a->rate*2}};p.trackLoop=true;p.trackLoopStart=8;p.trackLoopEnd=24;p.trackExportRaw=true;p.trackStemsEnabled=true;p.normaliseEnabled=true;p.normaliseLufs=true;p.targetLufs=-6;p.pitchSemitones=7;p.hasHost=true;p.hostBpm=90;p.trackStemMute[0]=true;auto muted=renderLoopAudio(AudioExportSnapshot::capture(p));int start=(int)std::llround(a->rate*4),frames=(int)std::llround(a->rate*8);if(muted.getNumSamples()!=frames)return 2043;double difference=0;for(int n=0;n<frames;++n)difference+=std::pow(muted.getSample(0,n)-a->buffer.getSample(0,start+n),2);if(std::sqrt(difference/frames)<.005)return 2044;p.trackStemMute[0]=false;p.trackStemGainDb[0]=-12;p.pitchSemitones=-5;p.hostBpm=160;auto attenuated=renderLoopAudio(AudioExportSnapshot::capture(p));if(attenuated.getNumSamples()!=frames)return 2045;float gain=juce::Decibels::decibelsToGain(-12.f),error=0;for(int ch=0;ch<attenuated.getNumChannels();++ch)for(int n=0;n<frames;++n){float expected=muted.getSample(ch,n)*(1-gain)+a->buffer.getSample(ch,start+n)*gain;error=juce::jmax(error,std::abs(expected-attenuated.getSample(ch,n)));}if(error>.002f)return 2046;p.trackStemsEnabled=false;auto bypass=renderLoopAudio(AudioExportSnapshot::capture(p));for(int ch=0;ch<bypass.getNumChannels();++ch)for(int n=0;n<frames;++n)if(bypass.getSample(ch,n)!=a->buffer.getSample(ch,start+n))return 2047;p.trackStemsEnabled=true;p.trackStemSolo[0]=true;auto solo=renderLoopAudio(AudioExportSnapshot::capture(p));if(solo.getNumSamples()!=frames||solo.getRMSLevel(0,0,frames)<1e-5f)return 2048;auto cancelled=renderLoopAudio(AudioExportSnapshot::capture(p),[]{return true;});if(cancelled.getNumSamples())return 2049;std::cout<<"Raw SCNet export: native 8-second duration, muted drums, -12 dB drum-fader linearity, drum solo, host tempo/pitch/normalization bypass, STEMS-off sample identity and cancellation passed; max mix error "<<error<<"\n";return 0;}
